def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    dangerous_prev.append(bid)

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    urgency += min(0.5, 0.22 * no_water)
    if day >= 8:
        urgency += 0.1

    base = DAILY_SALARY * (0.28 + 0.42 * scarcity + urgency)

    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.35)
        return max(0.0, float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0
    danger_prev = max(dangerous_prev) if dangerous_prev else highest_prev

    if supply >= 22:
        target = max(DAILY_SALARY * 0.22, avg_prev * 0.72)
    elif supply >= 19:
        target = max(DAILY_SALARY * 0.38, avg_prev * 0.9)
    else:
        target = max(DAILY_SALARY * 0.55, danger_prev + 2.0)

    if highest_prev >= 100 and hp >= 5 and no_water == 0 and supply >= 19:
        target = min(target, DAILY_SALARY * 0.34)

    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.92)
    elif hp <= 4 or no_water >= 1:
        target = max(target, DAILY_SALARY * 0.72)

    bid = max(base, target)

    remaining_days = max(1, 10 - int(day) + 1)
    reserve_floor = DAILY_SALARY * 0.22 * remaining_days
    spend_cap = budget
    if hp >= 5 and no_water == 0:
        spend_cap = max(0.0, budget - reserve_floor)
        if spend_cap <= 0:
            spend_cap = min(budget, DAILY_SALARY * 0.4)

    if supply <= 17 and (hp <= 4 or no_water >= 1):
        spend_cap = budget

    bid = min(bid, spend_cap, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((opp_id, o))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Baseline target from yesterday: follow the strongest surviving pattern.
    base = DAILY_SALARY * 0.55
    if yesterday_bids:
        highest = max(yesterday_bids)
        second = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest

        # If someone was extremely aggressive and survived, try to match slightly above risk tier.
        if highest >= DAILY_SALARY * 0.85:
            base = second + 5.0
        else:
            # Otherwise, bid around the upper mid to beat cautious bidders.
            base = max(base, second + 2.5)

    # Pressure adjustments: low HP or many no-water days => bid harder.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        base *= 1.35
    elif my_hp <= 4.0 or my_no_water_days == 1:
        base *= 1.15

    # Supply scaling: when supply is low, competition is higher.
    if supply <= float(MIN_SUPPLY):
        base *= 1.20
    elif supply >= float(MAX_SUPPLY):
        base *= 0.95

    # Convert base to a bid cap based on affordability.
    # Keep some budget for future days (10-day episode): spend at most ~35% of current budget.
    spend_cap = my_budget * 0.35
    bid = min(base, spend_cap)

    # Ensure we can still bid a meaningful amount.
    min_bid = 0.0
    if my_hp <= 2.0:
        min_bid = DAILY_SALARY * 0.6
    elif my_no_water_days >= 2:
        min_bid = DAILY_SALARY * 0.5
    bid = max(bid, min_bid)

    # Final clamp to budget.
    bid = min(bid, my_budget)
    if bid < 0.0:
        bid = 0.0
    return bid

